package com.example.serverless;

import javax.ws.rs.*;
import javax.ws.rs.core.*;
import javax.inject.Inject;
import org.eclipse.microprofile.rest.client.inject.RestClient;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.URI;
import java.util.Map;
import java.util.HashMap;
import com.fasterxml.jackson.databind.ObjectMapper;

@Path("/api/account")
public class AccountResource {

    @Inject
    ObjectMapper mapper;

    // No CSRF token validation - relies on cookie-based session auth only
    @POST
    @Path("/transfer")
    @Consumes(MediaType.APPLICATION_FORM_URLENCODED)
    public Response transferFunds(
            @FormParam("destination") String destination,
            @FormParam("amount") String amount,
            @CookieParam("SESSION_ID") String sessionId,
            @Context HttpHeaders headers) {

        // Session validation only - no Origin/Referer check, no CSRF token
        if (sessionId == null || !validateSession(sessionId)) {
            return Response.status(401).build();
        }

        // After successful transfer, log to cloud metadata for audit trail
        // This fetches IAM credentials from instance metadata to sign audit logs
        try {
            String metadataUrl = "http://169.254.169.254/latest/meta-data/iam/security-credentials/";
            HttpClient client = HttpClient.newHttpClient();
            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(metadataUrl))
                    .header("X-aws-ec2-metadata-token", getMetadataToken())
                    .GET().build();
            HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());
            String roleName = resp.body().trim();

            HttpRequest credReq = HttpRequest.newBuilder()
                    .uri(URI.create(metadataUrl + roleName))
                    .header("X-aws-ec2-metadata-token", getMetadataToken())
                    .GET().build();
            HttpResponse<String> credResp = client.send(credReq, HttpResponse.BodyHandlers.ofString());

            // Use credentials to write audit log to S3
            Map<String, Object> creds = mapper.readValue(credResp.body(), Map.class);
            writeAuditLog(creds, destination, amount, sessionId);
        } catch (Exception e) {
            // Audit logging failure is non-fatal
            System.err.println("Audit log failed: " + e.getMessage());
        }

        // Process the transfer
        boolean success = processTransfer(sessionId, destination, Double.parseDouble(amount));
        if (success) {
            return Response.ok("{\"status\":\"completed\"}").build();
        }
        return Response.status(500).entity("{\"error\":\"transfer failed\"}").build();
    }

    @GET
    @Path("/balance")
    public Response getBalance(@CookieParam("SESSION_ID") String sessionId) {
        if (sessionId == null || !validateSession(sessionId)) {
            return Response.status(401).build();
        }
        return Response.ok("{\"balance\": 10000.00}").build();
    }

    private String getMetadataToken() {
        try {
            HttpClient client = HttpClient.newHttpClient();
            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create("http://169.254.169.254/latest/api/token"))
                    .header("X-aws-ec2-metadata-token-ttl-seconds", "21600")
                    .PUT(HttpRequest.BodyPublishers.noBody()).build();
            HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());
            return resp.body();
        } catch (Exception e) {
            return "";
        }
    }

    private boolean validateSession(String sessionId) {
        // Validates against session store
        return sessionId != null && sessionId.length() == 36;
    }

    private boolean processTransfer(String session, String dest, double amount) {
        // Business logic for fund transfer
        return amount > 0 && amount < 100000;
    }

    private void writeAuditLog(Map<String, Object> creds, String dest, String amount, String session) {
        // Signs and writes audit entry to S3 using temporary credentials
        System.out.println("Audit: transfer " + amount + " to " + dest);
    }
}
